using LabLedger.Data; using LabLedger.Models;
namespace LabLedger.Controllers;
public sealed class AuthController { private readonly UserRepository users=new(); public OperationResult Login(string name,string password){if(string.IsNullOrWhiteSpace(name)||string.IsNullOrEmpty(password))return OperationResult.Fail("Enter both username and password.");try{if(!users.Validate(name.Trim(),password))return OperationResult.Fail("The username or password is incorrect.");Session.Username=name.Trim();return OperationResult.Ok("Login successful.");}catch(Exception){return OperationResult.Fail("Login could not be completed because of a database error.");}} }
public sealed class EquipmentController { private readonly EquipmentRepository repo=new(); public OperationResult Add(string name,string asset,string category,string lab,string quantity){if(string.IsNullOrWhiteSpace(name))return OperationResult.Fail("Enter an equipment name.");if(string.IsNullOrWhiteSpace(asset))return OperationResult.Fail("Enter an asset ID.");if(string.IsNullOrWhiteSpace(category))return OperationResult.Fail("Choose a category.");if(string.IsNullOrWhiteSpace(lab))return OperationResult.Fail("Enter a lab.");if(!int.TryParse(quantity,out int n)||n<1||n>1000)return OperationResult.Fail("Quantity must be a whole number from 1 to 1000.");try{if(repo.AssetExists(asset.Trim()))return OperationResult.Fail("That asset ID already exists.");repo.Add(new Equipment{Name=name.Trim(),AssetId=asset.Trim(),Category=category.Trim(),Lab=lab.Trim(),TotalQuantity=n,AvailableQuantity=n});return OperationResult.Ok("Equipment saved successfully.");}catch(Exception){return OperationResult.Fail("Equipment could not be saved. Check the details and try again.");}} public List<Equipment> List(string search=""){return repo.GetAll(search.Trim());} public OperationResult Delete(int id){try{var e=repo.Get(id);if(e is null)return OperationResult.Fail("Equipment was not found.");if(e.AvailableQuantity<e.TotalQuantity)return OperationResult.Fail("This item has units on loan and cannot be deleted.");repo.Delete(id);return OperationResult.Ok("Equipment deleted.");}catch(Exception){return OperationResult.Fail("Equipment could not be deleted.");}} }
public sealed class LoanController {private readonly EquipmentRepository equipment=new();private readonly LoanRepository loans=new();public OperationResult Borrow(int id,string student,string quantity){if(string.IsNullOrWhiteSpace(student))return OperationResult.Fail("Enter a student ID.");if(!int.TryParse(quantity,out int n)||n<1)return OperationResult.Fail("Quantity must be a whole number of at least 1.");try{var e=equipment.Get(id);if(e is null)return OperationResult.Fail("Equipment was not found.");if(n>e.AvailableQuantity)return OperationResult.Fail("There are not enough units available.");loans.Borrow(id,student.Trim(),n);return OperationResult.Ok("Equipment borrowed successfully.");}catch(Exception ex){return OperationResult.Fail(ex is InvalidOperationException?ex.Message:"The loan could not be recorded.");}}public OperationResult Return(int id,string student,string quantity){if(string.IsNullOrWhiteSpace(student))return OperationResult.Fail("Enter a student ID.");if(!int.TryParse(quantity,out int n)||n<1)return OperationResult.Fail("Quantity must be a whole number of at least 1.");try{loans.Return(id,student.Trim(),n);return OperationResult.Ok("Equipment returned successfully.");}catch(Exception ex){return OperationResult.Fail(ex is InvalidOperationException?ex.Message:"The return could not be recorded.");}}}
public sealed class StatisticsController {public EquipmentStatistics Get(){return new StatisticsRepository().Get();}}
